import AREAS from '../data/areas.json';
import FARES from '../data/fares.json';
import { BUSINESS } from '../data/business';

/**
 * Bengaluru service-area landing pages (/taxi-service-in-{slug}).
 * Data in data/areas.json is generated by scripts/build-areas.py: coordinates from OpenStreetMap,
 * road distance/time from OSRM to the airport, the city centre and each outstation route.
 */
export const AREA_PREFIX = '/taxi-service-in-';
export const AIRPORT = { name: 'Kempegowda International Airport', short: 'Bangalore Airport (KIA)', coord: '13.1986,77.7066' };

export const ZONES = [
  { key: 'central', label: 'Central Bengaluru' },
  { key: 'north', label: 'North Bengaluru' },
  { key: 'east', label: 'East Bengaluru' },
  { key: 'south', label: 'South Bengaluru' },
  { key: 'west', label: 'West Bengaluru' },
];

export const AREAS_META = {
  title: 'Taxi Service Across Bangalore | Areas We Serve – Taxi House',
  description: 'Airport taxi, outstation and local cabs from every part of Bengaluru — Whitefield, Electronic City, HSR Layout, Hebbal, Yelahanka, Jayanagar and 250+ more areas. Fixed all-in fares, 24×7.',
  path: '/areas',
};

const BY_SLUG = new Map(AREAS.map((a) => [a.slug, a]));
export const allAreas = () => AREAS;
export const getArea = (slug) => BY_SLUG.get(slug) || null;
export const areaPath = (a) => `${AREA_PREFIX}${a.slug}`;
export const areaFromPath = (pathname) => {
  const m = /^\/taxi-service-in-([a-z0-9-]+)\/?$/.exec(pathname);
  return m ? getArea(m[1]) : null;
};


const coordStr = (a) => `${a.lat.toFixed(5)},${a.lng.toFixed(5)}`;
const pickupLabel = (a) => `${a.name}, Bengaluru`;
const q = encodeURIComponent;

/** Booking-card deep links with the area pre-filled as pickup (BookingCard reads these params). */
export const bookLinks = (a) => ({
  outstation: `/?type=outstation&trip=one-way&pickup=${q(pickupLabel(a))}&pickupCoord=${coordStr(a)}#book`,
  route: (r) => `/?type=outstation&trip=one-way&pickup=${q(pickupLabel(a))}&pickupCoord=${coordStr(a)}&drop=${q(r.drop)}&dropCoord=${r.coord}#book`,
  toAirport: `/?type=airport&airport=to-airport&pickup=${q(pickupLabel(a))}&pickupCoord=${coordStr(a)}#book`,
  fromAirport: `/?type=airport&airport=from-airport&drop=${q(pickupLabel(a))}&dropCoord=${coordStr(a)}#book`,
  local: `/?type=local&pickup=${q(pickupLabel(a))}&pickupCoord=${coordStr(a)}#book`,
});

export const routesFor = (a) => FARES.routes
  .map((r) => ({ ...r, km: a.routes?.[r.slug]?.km ?? null, minutes: a.routes?.[r.slug]?.min ?? null }))
  .filter((r) => r.km);

export const nearbyAreas = (a) => (a.nearby || []).map(getArea).filter(Boolean);

const cheapestOneWayRate = () => Math.min(...FARES.fallbackCars
  .filter((c) => c.available_categories?.includes('outstation') && c.price_per_km_one_way > 0)
  .map((c) => c.price_per_km_one_way));

/** Unique, data-driven title + description per area (also used by the prerender step). */
export function areaMeta(a) {
  const air = a.airport;
  const title = `Taxi Service in ${a.name}, Bangalore | Airport & Outstation Cabs`;
  const description = `Book a cab in ${a.name}: fixed-fare airport taxi to KIA (${air.km} km), `
    + `one-way outstation drops from ₹${cheapestOneWayRate()}/km and 8-hour local rentals. `
    + `Fixed all-in fares, 24×7. Call ${BUSINESS.phoneDisplay}.`;
  return { title, description, path: areaPath(a) };
}

export function fmtMin(min) {
  const m = Math.round(min || 0);
  if (m < 60) return `${m} min`;
  const h = Math.floor(m / 60);
  const r = m % 60;
  return r ? `${h} h ${r} min` : `${h} h`;
}

/** JSON-LD for an area page: breadcrumb + the taxi service scoped to this area. */
export function areaJsonLd(a, faq) {
  const url = `${BUSINESS.url}${areaPath(a)}`;
  return {
    '@context': 'https://schema.org',
    '@graph': [
      {
        '@type': 'BreadcrumbList',
        itemListElement: [
          { '@type': 'ListItem', position: 1, name: 'Home', item: `${BUSINESS.url}/` },
          { '@type': 'ListItem', position: 2, name: 'Areas we serve', item: `${BUSINESS.url}/areas` },
          { '@type': 'ListItem', position: 3, name: `Taxi service in ${a.name}`, item: url },
        ],
      },
      {
        '@type': 'TaxiService',
        '@id': `${url}#service`,
        name: `Taxi service in ${a.name}, Bengaluru`,
        url,
        provider: { '@id': `${BUSINESS.url}/#business` },
        areaServed: {
          '@type': 'Place',
          name: `${a.name}, Bengaluru`,
          geo: { '@type': 'GeoCoordinates', latitude: +a.lat.toFixed(5), longitude: +a.lng.toFixed(5) },
        },
      },
      {
        '@type': 'FAQPage',
        mainEntity: faq.map((f) => ({ '@type': 'Question', name: f.q, acceptedAnswer: { '@type': 'Answer', text: f.a } })),
      },
    ],
  };
}
